.footer-bottom { border-top: 1px solid rgba(255,255,255,0.1); padding-top: 24px; display: flex; align-items: center; justify-content: space-between; font-size: 13px; color: var(--gray-500); }

/* Testimonial */
.testimonial-card { background: var(--white); border-radius: var(--radius-lg); padding: 32px; border: 1px solid var(--gray-200); }
.testimonial-card blockquote { font-size: 16px; line-height: 1.7; color: var(--gray-700); margin-bottom: 20px; font-style: italic; }
.testimonial-author { display: flex; align-items: center; gap: 12px; }
.testimonial-avatar { width: 44px; height: 44px; border-radius: 50%; background: var(--primary-light); display: flex; align-items: center; justify-content: center; font-weight: 700; color: var(--primary); font-size: 16px; }
.testimonial-name { font-weight: 600; font-size: 15px; }
.testimonial-role { font-size: 13px; color: var(--gray-500); }

/* Cookie Banner */
.cookie-banner { position: fixed; bottom: 0; left: 0; right: 0; background: var(--white); border-top: 1px solid var(--gray-200); padding: 20px 24px; z-index: 2000; box-shadow: 0 -4px 20px rgba(0,0,0,0.1); display: flex; align-items: center; justify-content: space-between; gap: 24px; }
.cookie-banner.hidden { display: none; }
.cookie-banner p { font-size: 14px; color: var(--gray-700); flex: 1; }
.cookie-actions { display: flex; gap: 12px; align-items: center; flex-shrink: 0; }

/* Cookie Modal */
.cookie-modal-overlay { position: fixed; inset: 0; background: rgba(0,0,0,0.5); z-index: 3000; display: flex; align-items: center; justify-content: center; opacity: 0; pointer-events: none; transition: opacity 0.2s ease; }
.cookie-modal-overlay.active { opacity: 1; pointer-events: all; }
.cookie-modal { background: var(--white); border-radius: var(--radius-lg); padding: 32px; max-width: 520px; width: 90%; max-height: 80vh; overflow-y: auto; }
.cookie-modal h3 { margin-bottom: 8px; }
.cookie-modal > p { font-size: 14px; color: var(--gray-500); margin-bottom: 24px; }
.cookie-category { display: flex; align-items: center; justify-content: space-between; padding: 16px 0; border-top: 1px solid var(--gray-200); }
.cookie-category-info h4 { font-size: 15px; margin-bottom: 2px; }
.cookie-category-info p { font-size: 13px; color: var(--gray-500); }

/* Toggle Switch */
.toggle-switch { position: relative; width: 48px; height: 26px; flex-shrink: 0; }
.toggle-switch input { opacity: 0; width: 0; height: 0; }
.toggle-slider { position: absolute; inset: 0; background: var(--gray-300); border-radius: 26px; cursor: pointer; transition: background var(--transition); }
.toggle-slider::before { content: ''; position: absolute; width: 20px; height: 20px; border-radius: 50%; background: var(--white); top: 3px; left: 3px; transition: transform var(--transition); }
.toggle-switch input:checked + .toggle-slider { background: var(--primary); }
.toggle-switch input:checked + .toggle-slider::before { transform: translateX(22px); }

/* Pricing Toggle */
.pricing-toggle-wrap { display: flex; align-items: center; justify-content: center; gap: 16px; margin-bottom: 48px; }
.pricing-toggle-wrap span { font-size: 15px; font-weight: 500; color: var(--gray-500); }
.pricing-toggle-wrap span.active { color: var(--dark); font-weight: 600; }
.pricing-toggle { position: relative; width: 56px; height: 30px; background: var(--primary); border-radius: 30px; cursor: pointer; border: none; transition: background var(--transition); }
.pricing-toggle::before { content: ''; position: absolute; width: 24px; height: 24px; border-radius: 50%; background: var(--white); top: 3px; left: 3px; transition: transform var(--transition); }
.pricing-toggle.annual::before { transform: translateX(26px); }

/* Plan Cards */
.plan-cards { display: grid; grid-template-columns: repeat(4, 1fr); gap: 24px; margin-bottom: 64px; }
.plan-card { background: var(--white); border: 2px solid var(--gray-200); border-radius: var(--radius-lg); padding: 32px; position: relative; display: flex; flex-direction: column; }
.plan-card.featured { border-color: var(--primary); box-shadow: var(--shadow-lg); }
.plan-card .badge { position: absolute; top: -12px; left: 50%; transform: translateX(-50%); }
.plan-name { font-size: 20px; font-weight: 700; margin-bottom: 8px; }
.plan-price { font-size: 40px; font-weight: 800; margin-bottom: 4px; }
.plan-price span { font-size: 16px; font-weight: 400; color: var(--gray-500); }
.plan-period { font-size: 14px; color: var(--gray-500); margin-bottom: 24px; }
.plan-features { list-style: none; margin-bottom: 24px; flex: 1; }
.plan-features li { padding: 6px 0; font-size: 14px; color: var(--gray-700); display: flex; align-items: flex-start; gap: 8px; }
.plan-features li::before { content: '\2713'; color: var(--green); font-weight: 700; flex-shrink: 0; }
.plan-card .btn { width: 100%; }

/* Team Slider */
.team-slider-wrap { max-width: 480px; margin: 0 auto 48px; text-align: center; }
.team-slider-label { font-size: 15px; color: var(--gray-700); margin-bottom: 12px; font-weight: 500; }
.team-slider-value { font-size: 28px; font-weight: 800; color: var(--primary); margin-bottom: 12px; }
input[type="range"] { -webkit-appearance: none; width: 100%; height: 6px; border-radius: 3px; background: var(--gray-200); outline: none; }
input[type="range"]::-webkit-slider-thumb { -webkit-appearance: none; width: 24px; height: 24px; border-radius: 50%; background: var(--primary); cursor: pointer; box-shadow: var(--shadow-sm); }

/* Comparison Table */
.comparison-table-wrap { overflow-x: auto; margin-bottom: 64px; }
.comparison-table { width: 100%; border-collapse: collapse; }
.comparison-table th, .comparison-table td { padding: 14px 20px; text-align: left; font-size: 14px; border-bottom: 1px solid var(--gray-200); }
.comparison-table th { font-weight: 600; background: var(--gray-50); position: sticky; top: 0; }
.comparison-table th:first-child { text-align: left; }
.comparison-table th:not(:first-child) { text-align: center; }
.comparison-table td:not(:first-child) { text-align: center; color: var(--gray-700); }
.comparison-table .check { color: var(--green); font-weight: 700; }
.comparison-table .dash { color: var(--gray-300); }
.comparison-table-toggle { display: flex; justify-content: center; margin-bottom: 24px; }
.comparison-table-section { max-height: 0; overflow: hidden; transition: max-height 0.4s ease; }
.comparison-table-section.expanded { max-height: 2000px; }

/* FAQ Accordion */
.faq-list { max-width: 768px; margin: 0 auto; }
.faq-item { border-bottom: 1px solid var(--gray-200); }
.faq-question { width: 100%; display: flex; align-items: center; justify-content: space-between; padding: 20px 0; background: none; border: none; font-size: 16px; font-weight: 600; text-align: left; color: var(--dark); cursor: pointer; gap: 16px; }
.faq-question:hover { color: var(--primary); }
.faq-icon { width: 24px; height: 24px; flex-shrink: 0; transition: transform 0.2s ease; }
.faq-item.open .faq-icon { transform: rotate(45deg); }
.faq-answer { max-height: 0; overflow: hidden; transition: max-height 0.3s ease; }
.faq-answer p { padding: 0 0 20px; font-size: 15px; color: var(--gray-500); line-height: 1.7; }

/* Auth pages */
.auth-page { min-height: 100vh; display: flex; }
.auth-form-wrap { flex: 1; display: flex; align-items: center; justify-content: center; padding: 40px; }
.auth-form { width: 100%; max-width: 420px; }
.auth-form h1 { font-size: 28px; margin-bottom: 32px; }
.auth-social-btn { display: flex; align-items: center; justify-content: center; gap: 12px; width: 100%; padding: 12px; border: 1px solid var(--gray-200); border-radius: var(--radius-sm); background: var(--white); font-size: 15px; font-weight: 500; color: var(--dark); margin-bottom: 12px; transition: all var(--transition); }
.auth-social-btn:hover { border-color: var(--gray-300); background: var(--gray-50); }
.auth-social-btn svg { width: 20px; height: 20px; }
.auth-divider { display: flex; align-items: center; gap: 16px; margin: 24px 0; color: var(--gray-500); font-size: 14px; }
.auth-divider::before, .auth-divider::after { content: ''; flex: 1; height: 1px; background: var(--gray-200); }
.auth-input-group { margin-bottom: 16px; }
.auth-input-group label { display: block; font-size: 14px; font-weight: 500; margin-bottom: 6px; color: var(--gray-700); }
.auth-input-group input { width: 100%; padding: 12px 16px; border: 1px solid var(--gray-200); border-radius: var(--radius-sm); font-size: 15px; transition: border-color var(--transition); }
.auth-input-group input:focus { outline: none; border-color: var(--primary); box-shadow: 0 0 0 3px rgba(24,104,219,0.1); }
.auth-footer { margin-top: 24px; font-size: 13px; color: var(--gray-500); line-height: 1.6; }
.auth-footer a { color: var(--primary); }
.auth-switch { margin-top: 24px; text-align: center; font-size: 14px; color: var(--gray-500); }
.auth-switch a { font-weight: 600; }
.auth-sidebar { width: 480px; background: linear-gradient(135deg, #1868DB 0%, #7c3aed 100%); color: var(--white); display: flex; flex-direction: column; justify-content: center; padding: 64px; }
.auth-sidebar blockquote { font-size: 20px; line-height: 1.6; margin-bottom: 24px; font-style: italic; }
.auth-sidebar .testimonial-name { color: var(--white); }
.auth-sidebar .testimonial-role { color: rgba(255,255,255,0.7); }

/* CTA Banner */
.cta-banner { background: linear-gradient(135deg, #1868DB 0%, #7c3aed 100%); color: var(--white); padding: 80px 0; text-align: center; }
.cta-banner h2 { font-size: 36px; margin-bottom: 16px; color: var(--white); }
.cta-banner p { font-size: 18px; opacity: 0.9; margin-bottom: 32px; }
.cta-banner .btn-primary { background: var(--white); color: var(--primary); }
.cta-banner .btn-primary:hover { background: var(--gray-100); color: var(--primary); }

/* Stats */
.stats-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 48px; text-align: center; }
.stat-number { font-size: 56px; font-weight: 800; color: var(--primary); margin-bottom: 8px; }
.stat-label { font-size: 16px; color: var(--gray-500); }

/* Feature with image placeholder */
.feature-block { display: grid; grid-template-columns: 1fr 1fr; gap: 64px; align-items: center; }
.feature-block.reverse { direction: rtl; }
.feature-block.reverse > * { direction: ltr; }
.feature-image { background: linear-gradient(135deg, var(--primary-light) 0%, #ede9fe 100%); border-radius: var(--radius-lg); aspect-ratio: 4/3; display: flex; align-items: center; justify-content: center; }
.feature-image-inner { width: 80%; height: 70%; background: var(--white); border-radius: var(--radius-md); box-shadow: var(--shadow-lg); display: flex; align-items: center; justify-content: center; font-size: 14px; color: var(--gray-500); }
.feature-content h2 { font-size: 32px; margin-bottom: 16px; }
.feature-content p { font-size: 16px; color: var(--gray-500); margin-bottom: 24px; line-height: 1.7; }

/* Integrations */
.integrations-logos { display: flex; flex-wrap: wrap; justify-content: center; gap: 24px; margin-top: 32px; }
.integration-item { width: 80px; height: 80px; background: var(--white); border: 1px solid var(--gray-200); border-radius: var(--radius-md); display: flex; align-items: center; justify-content: center; font-size: 11px; font-weight: 600; color: var(--gray-500); text-align: center; transition: all var(--transition); }
.integration-item:hover { border-color: var(--primary); box-shadow: var(--shadow-sm); }

/* Mobile menu */
.mobile-menu { display: none; position: fixed; top: 64px; left: 0; right: 0; bottom: 0; background: var(--white); z-index: 999; padding: 24px; flex-direction: column; gap: 16px; }
.mobile-menu.active { display: flex; }
.mobile-menu a { font-size: 18px; padding: 12px 0; border-bottom: 1px solid var(--gray-100); color: var(--dark); font-weight: 500; }

/* Responsive */
@media (max-width: 1024px) {
  .grid-4, .plan-cards { grid-template-columns: repeat(2, 1fr); }
  .footer-grid { grid-template-columns: repeat(3, 1fr); }
  .feature-block { grid-template-columns: 1fr; gap: 32px; }
  .feature-block.reverse { direction: ltr; }
  .auth-sidebar { display: none; }
}

@media (max-width: 768px) {
  .section { padding: 48px 0; }
  .section-title { font-size: 28px; }
  .grid-2, .grid-3 { grid-template-columns: 1fr; }
  .plan-cards { grid-template-columns: 1fr; }
  .stats-grid { grid-template-columns: 1fr; gap: 32px; }
  .nav-links { display: none; }
  .nav-actions .btn { display: none; }
  .mobile-toggle { display: block; }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
  .logo-bar-logos { gap: 24px; }
  .cookie-banner { flex-direction: column; text-align: center; }
  .comparison-table { font-size: 12px; }
  .comparison-table th, .comparison-table td { padding: 10px 8px; }
}

/* ClipCast Design System */
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap');

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --primary: #1868DB;
  --primary-dark: #1254b5;
  --primary-light: #e8f0fd;
  --accent: #FF613D;
  --accent-light: #fff0ec;
  --dark: #292A2E;
  --gray-900: #1a1a2e;
  --gray-700: #4a4a5a;
  --gray-500: #6b7280;
  --gray-300: #d1d5db;
  --gray-200: #e5e7eb;
  --gray-100: #f3f4f6;
  --gray-50: #f9fafb;
  --white: #ffffff;
  --green: #10b981;
  --purple: #7c3aed;
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
  --shadow-md: 0 4px 12px rgba(0,0,0,0.08);
  --shadow-lg: 0 8px 30px rgba(0,0,0,0.12);
  --shadow-xl: 0 20px 60px rgba(0,0,0,0.15);
  --transition: 0.2s ease;
}

html { scroll-behavior: smooth; }
body { font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif; color: var(--dark); line-height: 1.6; -webkit-font-smoothing: antialiased; }
