h1, h2, h3, h4, h5, h6 { line-height: 1.2; font-weight: 700; }

.container { max-width: 1200px; margin: 0 auto; padding: 0 24px; }
.section { padding: 80px 0; }
.section-alt { background: var(--gray-50); }

/* Buttons */
.btn { display: inline-flex; align-items: center; justify-content: center; gap: 8px; padding: 12px 28px; border-radius: 50px; font-weight: 600; font-size: 16px; border: none; transition: all var(--transition); text-decoration: none; }
.btn-primary { background: var(--primary); color: var(--white); }
